-- Esquema MySQL 8.x. Se recomienda npm run db:init para crear tablas y horarios.

CREATE DATABASE IF NOT EXISTS virelia_afiliados CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE virelia_afiliados;
CREATE TABLE IF NOT EXISTS users(id VARCHAR(36) PRIMARY KEY,email VARCHAR(200) UNIQUE NOT NULL,password_hash VARCHAR(200) NOT NULL,nombres VARCHAR(100) NOT NULL,apellidos VARCHAR(100) NOT NULL,tipo_documento VARCHAR(10) NOT NULL,documento VARCHAR(30) UNIQUE NOT NULL,nacimiento DATE NOT NULL,telefono VARCHAR(20) NOT NULL,direccion VARCHAR(200) NOT NULL,ciudad VARCHAR(100) NOT NULL,estado VARCHAR(30) DEFAULT 'Activo',regimen VARCHAR(40) DEFAULT 'Subsidiado',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS sessions(token_hash CHAR(64) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,expires_at DATETIME NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS beneficiaries(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,nombre VARCHAR(150) NOT NULL,documento VARCHAR(30) NOT NULL,parentesco VARCHAR(30) NOT NULL,nacimiento DATE NOT NULL,UNIQUE(user_id,documento),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(36) PRIMARY KEY,payload JSON NOT NULL,delivered TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE DATABASE IF NOT EXISTS virelia_citas CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE virelia_citas;
CREATE TABLE IF NOT EXISTS slots(id VARCHAR(36) PRIMARY KEY,especialidad VARCHAR(80) NOT NULL,profesional VARCHAR(100) NOT NULL,sede VARCHAR(100) NOT NULL,fecha DATE NOT NULL,hora VARCHAR(5) NOT NULL,available TINYINT DEFAULT 1,UNIQUE(profesional,fecha,hora));
CREATE TABLE IF NOT EXISTS appointments(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,slot_id VARCHAR(36) NOT NULL,estado VARCHAR(30) DEFAULT 'Agendada',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(slot_id) REFERENCES slots(id),INDEX(user_id));
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(36) PRIMARY KEY,payload JSON NOT NULL,delivered TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE DATABASE IF NOT EXISTS virelia_documentos CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE virelia_documentos;
CREATE TABLE IF NOT EXISTS documents(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,tipo VARCHAR(60) NOT NULL,titulo VARCHAR(160) NOT NULL,estado VARCHAR(30) NOT NULL,detalle VARCHAR(2000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(36) PRIMARY KEY,payload JSON NOT NULL,delivered TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);

CREATE DATABASE IF NOT EXISTS virelia_notificaciones CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE virelia_notificaciones;
CREATE TABLE IF NOT EXISTS notifications(id VARCHAR(36) PRIMARY KEY,event_id VARCHAR(36) UNIQUE NOT NULL,user_id VARCHAR(36) NOT NULL,titulo VARCHAR(160) NOT NULL,mensaje VARCHAR(2000) NOT NULL,link VARCHAR(150) NOT NULL,leida TINYINT DEFAULT 0,email_status VARCHAR(30) DEFAULT 'Sin configurar',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS preferences(user_id VARCHAR(36) PRIMARY KEY,email_enabled TINYINT DEFAULT 1);

CREATE DATABASE IF NOT EXISTS virelia_atencion CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE virelia_atencion;
CREATE TABLE IF NOT EXISTS cases(id VARCHAR(36) PRIMARY KEY,user_id VARCHAR(36) NOT NULL,radicado VARCHAR(40) UNIQUE NOT NULL,tipo VARCHAR(30) NOT NULL,asunto VARCHAR(150) NOT NULL,descripcion VARCHAR(2000) NOT NULL,estado VARCHAR(30) DEFAULT 'Radicada',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id));
CREATE TABLE IF NOT EXISTS messages(id VARCHAR(36) PRIMARY KEY,case_id VARCHAR(36) NOT NULL,mensaje VARCHAR(2000) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(case_id) REFERENCES cases(id));
CREATE TABLE IF NOT EXISTS outbox (id VARCHAR(36) PRIMARY KEY,payload JSON NOT NULL,delivered TINYINT DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
